import { Component } from '@angular/core';
import { jobSeeker } from 'src/app/auth/Models/jobSeeker';
import { ApplicationService } from 'src/app/service/application/application.service';
import { AuthService } from 'src/app/service/auth.service';
import { JobService } from 'src/app/service/job/job.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';
import { SeekerService } from 'src/app/service/seeker/seeker.service';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent {

// firstName! : string;

  constructor(private seekerService : SeekerService, private applicationService : ApplicationService){}

  id : number = Number(localStorage.getItem("id"));

 

  seeker!:jobSeeker;
 
 getSeekerById(id: number) {
  this.seekerService.getSeekerById(id).subscribe({
    next: (res) => {
      console.log("Response:", res);
      this.seeker = res;
      console.log("Name:", this.seeker.firstName);
    },
    error: (err) => console.log(err)
  });
}

applicationsById :  any[] =[];
 totalApplications = 0;


getApplicationsByJobseekerId(id : number){
  this.applicationService.getApplicationByjobSeekerId(id).subscribe({
    next : (result) =>{
      console.log(result);
      this.applicationsById=result ;
      this.totalApplications  = this.applicationsById.length;
      console.log(this.totalApplications);
    },
     error: (err) => {
      console.log(err);
    }
  });
}

 ngOnInit(){
    this.getSeekerById(this.id);
    this.getApplicationsByJobseekerId(this.id);
    console.log(this.totalApplications);
  }
}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Job Seeker Dashboard · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">


</head>
<body>
<div class="page">
<header class="topnav app">
  <div class="wrap">
    <a href="seeker-dashboard.html" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links app-links">
      <a href="seeker-dashboard.html" class="active">Dashboard</a>
      <a href="seeker-jobs.html">Find Jobs</a>
      <a href="seeker-applications.html">Applications</a>
      <a href="seeker-saved.html">Saved</a>
      <a href="seeker-profile.html">Profile</a>
    </nav>
    <div class="avatar">AM</div>
  </div>
</header>
<div class="app-shell">
<aside class="sidebar">
  <div class="sidebar-group">
    <span class="sidebar-label">General</span>
    <a href="seeker-dashboard.html" class="active"><span class="dot"></span>Dashboard</a>
    <a href="seeker-jobs.html"><span class="dot"></span>Browse Jobs</a>
    <a href="seeker-saved.html"><span class="dot"></span>Saved Jobs</a>
  </div>
  <div class="sidebar-group">
    <span class="sidebar-label">Career</span>
    <a href="seeker-applications.html"><span class="dot"></span>My Applications</a>
    <a href="seeker-profile.html"><span class="dot"></span>My Profile</a>
    <a href="seeker-resume.html"><span class="dot"></span>Resume &amp; Photo</a>
  </div>
</aside>
<main class="main">

<div class="page-title"> Welcome back, {{seeker?.firstName }}</div>
<div class="page-sub">Here's where your search stands.</div>
<div style="margin-bottom:24px;"><a href="seeker-jobs.html" class="btn btn-primary">Browse jobs</a></div>
<div class="card-row-3" style="margin-bottom:32px;">
  <div class="stat-card"><div class="n">{{ totalApplications }}</div><div class="l">Applications sent</div></div>
  <div class="stat-card"><div class="n">5</div><div class="l">Pending review</div><span class="sub">in progress</span></div>
  <div class="stat-card"><div class="n">3</div><div class="l">Approved</div><span class="sub">↑ offers</span></div>
</div>
<div class="card-row-3" style="margin-bottom:32px;grid-template-columns:1fr;max-width:220px;">
  <div class="stat-card"><div class="n">9</div><div class="l">Saved jobs</div></div>
</div>
<div class="section-head"><h2>Recent applications</h2></div>
<div class="table-wrap" style="margin-bottom:32px;">
  <table>
    <thead><tr><th>Role</th><th>Company</th><th>Applied</th><th>Status</th></tr></thead>
    <tbody>
      <tr><td>Backend Engineer</td><td>Nimbus Cloud</td><td>2 days ago</td><td><span class="chip chip-pending">Pending</span></td></tr>
      <tr><td>Product Designer</td><td>Fernwood Labs</td><td>5 days ago</td><td><span class="chip chip-approved">Approved</span></td></tr>
      <tr><td>Data Analyst</td><td>Harbor &amp; Finch</td><td>1 week ago</td><td><span class="chip chip-rejected">Rejected</span></td></tr>
    </tbody>
  </table>
</div>
<div class="section-head"><h2>Recommended for your skills</h2></div>
<div class="card-row">
  <div class="job-card"><div class="top"><h3 style="font-size:15px;">DevOps Engineer</h3><span class="chip chip-open">Open</span></div><div class="meta">Nimbus Cloud · Remote</div></div>
  <div class="job-card"><div class="top"><h3 style="font-size:15px;">Java Developer</h3><span class="chip chip-open">Open</span></div><div class="meta">Solstice Retail · Mumbai</div></div>
</div>

</main>
</div>
</div>
</body>
</html>
